#include "window.h"
#include "journalpath.h"
#include <QtWidgets>
#include <QSettings>
#include <QSqlQuery>
#include <QDesktopServices>
void Window::startPagerWorker(){if(pagerWorker_)pagerWorker_->shutdown();QSettings s(settingsFile_,QSettings::IniFormat);pagerSettings_.audioRoot=s.value("pager/audioRoot",QFileInfo(db_.databaseName()).absolutePath()+"/PrivateRadio/Audio").toString();pagerSettings_.expirySeconds=s.value("pager/expirySeconds",3600).toInt();pagerSettings_.relay=s.value("pager/relay",false).toBool();pagerSettings_.speech=speechSettings_;pagerWorker_=std::make_unique<PagerWorker>(db_.databaseName());pagerWorker_->configure(pagerSettings_);connect(pagerWorker_.get(),&PagerWorker::diagnostic,this,&Window::technical);pagerWorker_->start();}
void Window::pagerOptions(){QDialog dialog(this);dialog.setObjectName("pagerConfiguration");dialog.setWindowTitle("PrivateRadio — dossier des annonces vocales");dialog.resize(780,380);auto form=new QFormLayout(&dialog);auto path=new QLineEdit(QDir::toNativeSeparators(pagerSettings_.audioRoot));path->setObjectName("pagerAudioRoot");form->addRow("Dossier des annonces WAV et JSON",path);auto buttons=new QHBoxLayout;auto browse=new QPushButton("Parcourir…");browse->setMinimumHeight(38);auto open=new QPushButton("Ouvrir le dossier");buttons->addWidget(browse);buttons->addWidget(open);form->addRow(buttons);connect(browse,&QPushButton::clicked,&dialog,[&]{auto selected=QFileDialog::getExistingDirectory(&dialog,"Dossier local des annonces vocales",path->text());if(!selected.isEmpty())path->setText(QDir::toNativeSeparators(selected));});connect(open,&QPushButton::clicked,&dialog,[&]{auto p=normalizedTxtPath(path->text());if(!absoluteTxtPath(p)||!QFileInfo(p).isDir()||!QDesktopServices::openUrl(QUrl::fromLocalFile(p)))QMessageBox::warning(&dialog,"Dossier","Ce dossier est absent ou inaccessible.");});
 auto expiry=new QSpinBox;expiry->setObjectName("pagerExpiry");expiry->setRange(0,30*24*3600);expiry->setSpecialValueText("Sans expiration");expiry->setValue(pagerSettings_.expirySeconds);form->addRow("Expiration de diffusion (secondes)",expiry);
 auto relay=new QCheckBox("Relais PrivateRadio OFF — aucune transmission");relay->setObjectName("pagerRelay");relay->setChecked(pagerSettings_.relay);auto label=[relay]{relay->setText(relay->isChecked()?"Relais PrivateRadio ON — en attente d’adaptateur validé":"Relais PrivateRadio OFF — aucune transmission");};connect(relay,&QCheckBox::toggled,&dialog,label);label();form->addRow(relay);
 auto explanation=new QLabel("Pager ON sur un capcode actif génère son WAV et son manifeste JSON, même avec Voix locale OFF. Les fichiers sont privés : choisissez un dossier accessible uniquement aux comptes autorisés. Le relais distant reste non raccordé et ne contacte aucun serveur. L’expiration interdit la diffusion ; elle ne supprime ni audio ni historique.");explanation->setWordWrap(true);form->addRow(explanation);
 auto retry=new QPushButton("Réessayer les générations différées dans le dossier choisi");retry->setObjectName("pagerRetry");form->addRow(retry);bool reassign=false;connect(retry,&QPushButton::clicked,&dialog,[&]{reassign=true;retry->setText("Les tâches sans WAV seront réaffectées après Enregistrer");});
 auto box=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel);box->button(QDialogButtonBox::Save)->setText("Enregistrer");box->button(QDialogButtonBox::Cancel)->setText("Annuler");form->addRow(box);connect(box,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);connect(box,&QDialogButtonBox::accepted,&dialog,[&]{auto p=normalizedTxtPath(path->text());if(!absoluteTxtPath(p)||!QDir().mkpath(p)){QMessageBox::warning(&dialog,"Dossier","Choisissez un dossier absolu accessible.");return;}QTemporaryFile probe(QDir(p).filePath(".pager-write-test-XXXXXX"));if(!probe.open()||probe.write("POCSAG")!=6||!probe.flush()){QMessageBox::warning(&dialog,"Écriture","Écriture impossible dans le dossier choisi.");return;}QSettings settings(settingsFile_,QSettings::IniFormat);settings.setValue("pager/audioRoot",p);settings.setValue("pager/expirySeconds",expiry->value());settings.setValue("pager/relay",relay->isChecked());settings.sync();if(settings.status()!=QSettings::NoError){QMessageBox::warning(&dialog,"Configuration","Configuration non sauvegardée ; destination active conservée.");return;}pagerSettings_={p,expiry->value(),relay->isChecked(),speechSettings_};if(pagerWorker_)pagerWorker_->configure(pagerSettings_);if(reassign){QSqlQuery q(db_);q.prepare("UPDATE pager_jobs SET audio_path='',next_attempt_ms=0 WHERE generation_state IN ('pending','retry')");if(!q.exec()){QMessageBox::warning(&dialog,"Reprise","SQLite occupé ; les tâches restent conservées.");return;}q.finish();}dialog.accept();});
 dialog.exec();}
